%[text] # Comparison between the displacements of end effector and the axial end (ids-3010 and xl-80)
close all;
clear; clc;

set(groot, 'DefaultAxesFontName', 'Times New Roman', 'DefaultAxesFontSize', 12);
set(groot, 'DefaultTextFontName', 'Times New Roman', 'DefaultTextFontSize', 12);

GEOMETRIC_ERROR_MAP = 'data/X_positioning_error.mat';

%%
%[text] ## load data
tic;

% ------------------------ End effector displacement measured by IDS ------------------------
idsEndPath = char("D:\Sync\syncthing\Data\202406-mms-dynamics\ids results mat\20240530 IDS\XD_Y0_A3J80.mat");
idsEndData = load(idsEndPath);

% Positioning Error Removal of Displacement
idsEndData.DispWithPosErr = idsEndData.Displacement;
idsEndData.Displacement = remove_positioning_error(idsEndData.Time, idsEndData.DispWithPosErr, GEOMETRIC_ERROR_MAP, "isDraw", false);

% Denoise
idsEndData_filter = filter_kinematic_signal(idsEndData, "isDraw", false);


% ------------------------ Axial Displacement measured by IDS ------------------------
idsActPath = char("D:\Sync\syncthing\Data\202406-mms-dynamics\ids results mat\20240531 IDS\XA_Y0_A3J80.mat");
idsActData = load(idsActPath);

% Positioning Error Removal of Displacement
idsActData.DispWithPosErr = idsActData.Displacement;
idsActData.Displacement = remove_positioning_error(idsActData.Time, idsActData.DispWithPosErr, GEOMETRIC_ERROR_MAP, "isDraw", false);

% Denoise
idsActData_filter = filter_kinematic_signal(idsActData, "isDraw", false);


% ------------------------ End effector displacement measured by XL-80 ------------------------
xl80EndPath = char('D:\Sync\syncthing\Data\202406-mms-dynamics\xl80 results\20240530 xl80\XD-Y0_A3J80.csv');
xl80EndData = read_xl_csv(xl80EndPath);

% Positioning Error Removal of Displacement
xl80EndData.DispWithPosErr = -1 .* xl80EndData.Displacement;
xl80EndData.Displacement = remove_positioning_error(xl80EndData.Time, xl80EndData.DispWithPosErr, GEOMETRIC_ERROR_MAP, "isDraw", false);

% Denoise
xl80EndData_filter = filter_kinematic_signal(xl80EndData, "isDraw", false);

% ------------------------ Axial displacement measured by XL-80 ------------------------
xl80ActPath = char('D:\Sync\syncthing\Data\202406-mms-dynamics\xl80 results\20240531 xl80\XA_Y0A3J80-1.csv');
xl80ActData = read_xl_csv(xl80ActPath);

% Positioning Error Removal of Displacement
xl80ActData.DispWithPosErr = xl80ActData.Displacement;
xl80ActData.Displacement = remove_positioning_error(xl80ActData.Time, xl80ActData.DispWithPosErr, GEOMETRIC_ERROR_MAP, "isDraw", false);

% Denoise
xl80ActData_filter = filter_kinematic_signal(xl80ActData, "isDraw", false);

t = toc

fig1 = figure('Name','Original data');
plot(idsActData_filter.Time, idsActData_filter.Displacement,'DisplayName','Axial - IDS');
hold on;
plot(idsEndData_filter.Time, idsEndData_filter.Displacement,'DisplayName','End - IDS');
plot(xl80ActData_filter.Time, xl80ActData_filter.Displacement,'DisplayName','Axial - XL80');
plot(xl80EndData_filter.Time, xl80EndData_filter.Displacement,'DisplayName','End - XL80');
legend;
%%
%[text] ## Data alignment

%%
%[text] ## Comparison
%[output:97b39374]


% X轴A、D测点：X=-1000~X=-5500
% measData.Displacement = measData.Displacement - 1000 + measData.Displacement(1);
% X轴B测点：X=-3000~X=-7000
% measData.Displacement = -1 * measData.Displacement - 3000 + measData.Displacement(1);
% X轴C测点：X=-4200~X=-4300
% measData.Displacement = -1 * measData.Displacement - 4200 + measData.Displacement(1);
% X轴C测点：X=-6900~X=-7000
% measData.Displacement = -1 * measData.Displacement - 6900 + measData.Displacement(1);

%[output:2115717a]
%%
function measData = read_xl_csv(filePath)
% .csv file: xl-80 results
fid = fopen(filePath);
for ii = 1:100
    tline = fgetl(fid);
    if contains(tline,'Time,Measurement')
        break;
    end
end
fclose(fid);

opts = detectImportOptions(filePath,"FileType","delimitedtext","NumHeaderLines",ii - 1);
dataTable = readtable(filePath,opts);
measData = struct("Time",dataTable.Time,"Displacement",dataTable.Measurement);
measData.Displacement = -1.*measData.Displacement;
end

